// liftsep23.pl: a ProbLog program written in WebPPL by tddlog's
// scripts/problog2ppl.py, first order as it is written. A relation is an
// object from a tuple's key to {t: the tuple, v: whether it holds}, v a
// function of no arguments that says whether the tuple holds in the world
// being enumerated, memoized within it; each probabilistic fact is a coin of
// its own (`flip`), drawn where a world first reads it; a rule's instances
// are maps over the relations its body joins. The facts are lpFacts, which
// the runner reads from the facts file: {relation: [[argument ...,
// probability], ...]}. The queries are enumerated exactly, given the
// evidence.

var yes = function() { return true; };
var no = function() { return false; };
// a coin of probability p, drawn once in a world
var coin = function(p) { return mem(function() { return flip(p); }); };
var and = function(xs) { return function() { return all(function(x) { return x(); }, xs); }; };
var not = function(x) { return function() { return !x(); }; };
var keyOf = function(t) { return JSON.stringify(t); };
// whether the tuple t of r holds
var holds = function(r, t) { var e = r[keyOf(t)]; return e ? e.v : no; };
// the entry of t, if it is a tuple of r: none or one to map over
var probe = function(r, t) { var e = r[keyOf(t)]; return e ? [e] : []; };
// the entries of r by their values at positions ps (from 0)
var index = function(r, ps) {
  return _.groupBy(map(function(e) { return {k: keyOf(_.at(e.t, ps)), t: e.t, v: e.v}; }, _.values(r)), 'k');
};
// whether a tuple of the index's key k holds
var holdsAny = function(ix, k) {
  var es = ix[keyOf(k)] || [];
  return function() { return any(function(e) { return e.v(); }, es); };
};
// the choice of an annotated disjunction p1::h1; ...; pn::hn: whether each
// head is the one chosen, the k-th with probability pk and none with the rest
var choose = function(ps) {
  var rest = 1 - sum(ps);
  var vs = _.range(ps.length + (rest > 0 ? 1 : 0));
  var c = mem(function() { return categorical({ps: rest > 0 ? ps.concat([rest]) : ps, vs: vs}); });
  return map(function(k) { return function() { return c() === k; }; }, _.range(ps.length));
};
// the instances, [relation, tuple, holding] each, of relation `name`
var only = function(name, instances) { return filter(function(i) { return i[0] === name; }, instances); };
// the relation of base and instances: a tuple holds where its fact or one
// of its instances does
var relation = function(base, instances) {
  var entries = map(function(e) { return {k: keyOf(e.t), t: e.t, v: e.v}; }, _.values(base)).concat(
    map(function(i) { return {k: keyOf(i[1]), t: i[1], v: i[2]}; }, instances));
  return mapObject(function(k, es) {
    var vs = map(function(e) { return e.v; }, es);
    return {t: es[0].t, v: mem(function() { return any(function(x) { return x(); }, vs); })};
  }, _.groupBy(entries, 'k'));
};
// a relation of facts, [argument ..., probability] each
var relationOfFacts = function(rows) {
  return _.fromPairs(map(function(row) {
    var t = row.slice(0, row.length - 1), p = row[row.length - 1];
    return [keyOf(t), {t: t, v: p >= 1 ? yes : coin(p)}];
  }, rows));
};

var r_facts = relationOfFacts(lpFacts['r/1'] || []);
var t_facts = relationOfFacts(lpFacts['t/1'] || []);
var s1_facts = relationOfFacts(lpFacts['s1/2'] || []);
var s2_facts = relationOfFacts(lpFacts['s2/2'] || []);
var s3_facts = relationOfFacts(lpFacts['s3/2'] || []);

var r = r_facts;

var s1 = s1_facts;

var s1_by_1 = index(s1, [0]);
var instances_h30 = [].concat(
  // h30 :- r(X), s1(X,Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      return _.flatten(map(function(e2) {
        var Y = e2.t[1];
        return [['h30', [], and([e1.v, e2.v])]];
      }, (s1_by_1[keyOf([X])] || [])));
    }, _.values(r)));
  })()
);
var h30 = relation({}, instances_h30);

var s2 = s2_facts;

var instances_h31 = [].concat(
  // h31 :- s1(X,Y), s2(X,Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      var Y = e1.t[1];
      return _.flatten(map(function(e2) {
        return [['h31', [], and([e1.v, e2.v])]];
      }, probe(s2, [X, Y])));
    }, _.values(s1)));
  })()
);
var h31 = relation({}, instances_h31);

var s3 = s3_facts;

var instances_h32 = [].concat(
  // h32 :- s2(X,Y), s3(X,Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      var Y = e1.t[1];
      return _.flatten(map(function(e2) {
        return [['h32', [], and([e1.v, e2.v])]];
      }, probe(s3, [X, Y])));
    }, _.values(s2)));
  })()
);
var h32 = relation({}, instances_h32);

var t = t_facts;

var instances_h33 = [].concat(
  // h33 :- s3(X,Y), t(Y).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      var Y = e1.t[1];
      return _.flatten(map(function(e2) {
        return [['h33', [], and([e1.v, e2.v])]];
      }, probe(t, [Y])));
    }, _.values(s3)));
  })()
);
var h33 = relation({}, instances_h33);

var instances_q9_0 = [].concat(
  // q9_0 :- h30.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_0', [], e1.v]];
    }, probe(h30, [])));
  })(),
  // q9_0 :- h33.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_0', [], e1.v]];
    }, probe(h33, [])));
  })()
);
var q9_0 = relation({}, instances_q9_0);

var instances_q9_1 = [].concat(
  // q9_1 :- h31.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_1', [], e1.v]];
    }, probe(h31, [])));
  })(),
  // q9_1 :- h33.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_1', [], e1.v]];
    }, probe(h33, [])));
  })()
);
var q9_1 = relation({}, instances_q9_1);

var instances_q9_2 = [].concat(
  // q9_2 :- h32.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_2', [], e1.v]];
    }, probe(h32, [])));
  })(),
  // q9_2 :- h33.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_2', [], e1.v]];
    }, probe(h33, [])));
  })()
);
var q9_2 = relation({}, instances_q9_2);

var instances_q9_3 = [].concat(
  // q9_3 :- h30.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_3', [], e1.v]];
    }, probe(h30, [])));
  })(),
  // q9_3 :- h31.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_3', [], e1.v]];
    }, probe(h31, [])));
  })(),
  // q9_3 :- h32.
  (function() {
    return _.flatten(map(function(e1) {
      return [['q9_3', [], e1.v]];
    }, probe(h32, [])));
  })()
);
var q9_3 = relation({}, instances_q9_3);

var instances_q9 = [].concat(
  // q9 :- q9_0, q9_1, q9_2, q9_3.
  (function() {
    return _.flatten(map(function(e1) {
      return _.flatten(map(function(e2) {
        return _.flatten(map(function(e3) {
          return _.flatten(map(function(e4) {
            return [['q9', [], and([e1.v, e2.v, e3.v, e4.v])]];
          }, probe(q9_3, [])));
        }, probe(q9_2, [])));
      }, probe(q9_1, [])));
    }, probe(q9_0, [])));
  })()
);
var q9 = relation({}, instances_q9);

var instances_qw_0 = [].concat(
  // qw_0 :- h30.
  (function() {
    return _.flatten(map(function(e1) {
      return [['qw_0', [], e1.v]];
    }, probe(h30, [])));
  })(),
  // qw_0 :- h32.
  (function() {
    return _.flatten(map(function(e1) {
      return [['qw_0', [], e1.v]];
    }, probe(h32, [])));
  })()
);
var qw_0 = relation({}, instances_qw_0);

var instances_qw_1 = [].concat(
  // qw_1 :- h30.
  (function() {
    return _.flatten(map(function(e1) {
      return [['qw_1', [], e1.v]];
    }, probe(h30, [])));
  })(),
  // qw_1 :- h33.
  (function() {
    return _.flatten(map(function(e1) {
      return [['qw_1', [], e1.v]];
    }, probe(h33, [])));
  })()
);
var qw_1 = relation({}, instances_qw_1);

var instances_qw_2 = [].concat(
  // qw_2 :- h31.
  (function() {
    return _.flatten(map(function(e1) {
      return [['qw_2', [], e1.v]];
    }, probe(h31, [])));
  })(),
  // qw_2 :- h33.
  (function() {
    return _.flatten(map(function(e1) {
      return [['qw_2', [], e1.v]];
    }, probe(h33, [])));
  })()
);
var qw_2 = relation({}, instances_qw_2);

var instances_qw = [].concat(
  // qw :- qw_0, qw_1, qw_2.
  (function() {
    return _.flatten(map(function(e1) {
      return _.flatten(map(function(e2) {
        return _.flatten(map(function(e3) {
          return [['qw', [], and([e1.v, e2.v, e3.v])]];
        }, probe(qw_2, [])));
      }, probe(qw_1, [])));
    }, probe(qw_0, [])));
  })()
);
var qw = relation({}, instances_qw);

// component 0 bool
// component 1 bool
var model = function() {
  return [holds(qw, [])(),
          holds(q9, [])()];
};
Infer({method: 'enumerate'}, model);

